CREATE TABLE "audit_logs" ("id" UUID NOT NULL,"user_id" UUID,"module" VARCHAR(60) NOT NULL,"entity_type" VARCHAR(60) NOT NULL,"entity_id" VARCHAR(80),"action" VARCHAR(80) NOT NULL,"before_data" JSONB,"after_data" JSONB,"ip_address" VARCHAR(64),"user_agent" VARCHAR(500),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id"));
CREATE INDEX "audit_logs_created_at_idx" ON "audit_logs"("created_at");CREATE INDEX "audit_logs_module_idx" ON "audit_logs"("module");CREATE INDEX "audit_logs_action_idx" ON "audit_logs"("action");CREATE INDEX "audit_logs_user_id_idx" ON "audit_logs"("user_id");
